import{_ as n,o as a,c as e,ai as i}from"./chunks/framework.DvyodJJB.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"development/architecture.md","filePath":"development/architecture.md"}'),l={name:"development/architecture.md"};function p(t,s,r,o,c,d){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>System architecture and design overview of Aether.</p><h2 id="system-overview" tabindex="-1">System Overview <a class="header-anchor" href="#system-overview" aria-label="Permalink to &quot;System Overview&quot;">​</a></h2><p>Aether is a command-line tool for orchestrating FHIR data processing pipelines. The system follows functional programming principles with clear separation of concerns between data models, business logic, and side effects (I/O, HTTP).</p><h3 id="high-level-architecture" tabindex="-1">High-Level Architecture <a class="header-anchor" href="#high-level-architecture" aria-label="Permalink to &quot;High-Level Architecture&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│   CLI User  │</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       │ Commands (pipeline, job)</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│          Aether CLI (Go)                │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────┐   │</span></span>
<span class="line"><span>│  │  Cobra Commands                 │   │</span></span>
<span class="line"><span>│  │  - pipeline start/continue      │   │</span></span>
<span class="line"><span>│  │  - job list/status/logs         │   │</span></span>
<span class="line"><span>│  └──────────┬──────────────────────┘   │</span></span>
<span class="line"><span>│             ▼                            │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────┐   │</span></span>
<span class="line"><span>│  │  Pipeline Orchestrator          │   │</span></span>
<span class="line"><span>│  │  (Pure Functions + State)       │   │</span></span>
<span class="line"><span>│  └──────────┬──────────────────────┘   │</span></span>
<span class="line"><span>│             ▼                            │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────┐   │</span></span>
<span class="line"><span>│  │  Services (Side Effects)        │   │</span></span>
<span class="line"><span>│  │  - HTTP Client (TORCH, DIMP)    │   │</span></span>
<span class="line"><span>│  │  - File I/O (Import/Save)       │   │</span></span>
<span class="line"><span>│  │  - State Persistence (JSON)     │   │</span></span>
<span class="line"><span>│  └──────────┬──────────────────────┘   │</span></span>
<span class="line"><span>└─────────────┼──────────────────────────┘</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>    ┌─────────┴──────────┐</span></span>
<span class="line"><span>    ▼                    ▼</span></span>
<span class="line"><span>┌──────────┐        ┌──────────────┐</span></span>
<span class="line"><span>│ TORCH    │        │ DIMP         │</span></span>
<span class="line"><span>│ Server   │        │ Service      │</span></span>
<span class="line"><span>└──────────┘        └──────────────┘</span></span>
<span class="line"><span>    ▲                    ▲</span></span>
<span class="line"><span>    │                    │</span></span>
<span class="line"><span>    └────────────────────┘</span></span>
<span class="line"><span>     External Services</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br></div></div><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>The codebase is organized for clarity and maintainability:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>aether/</span></span>
<span class="line"><span>├── cmd/                      # CLI entry points</span></span>
<span class="line"><span>│   ├── root.go               # Root command (aether)</span></span>
<span class="line"><span>│   ├── pipeline.go           # Pipeline commands (start, continue, status)</span></span>
<span class="line"><span>│   └── job.go                # Job management (list, logs, delete)</span></span>
<span class="line"><span>├── internal/</span></span>
<span class="line"><span>│   ├── models/               # Domain models (immutable)</span></span>
<span class="line"><span>│   │   ├── job.go            # PipelineJob, JobStatus</span></span>
<span class="line"><span>│   │   ├── step.go           # PipelineStep, StepStatus</span></span>
<span class="line"><span>│   │   ├── config.go         # ProjectConfig</span></span>
<span class="line"><span>│   │   └── validation.go     # Model validation</span></span>
<span class="line"><span>│   ├── pipeline/             # Pipeline orchestration (pure)</span></span>
<span class="line"><span>│   │   ├── job.go            # Job initialization</span></span>
<span class="line"><span>│   │   ├── import.go         # Import step dispatcher (torch/local/http)</span></span>
<span class="line"><span>│   │   ├── validation.go     # FHIR validation step</span></span>
<span class="line"><span>│   │   └── dimp.go           # DIMP pseudonymization step</span></span>
<span class="line"><span>│   ├── services/             # Side effects (I/O, HTTP)</span></span>
<span class="line"><span>│   │   ├── importer.go       # Local file import</span></span>
<span class="line"><span>│   │   ├── downloader.go     # HTTP download</span></span>
<span class="line"><span>│   │   ├── torch_client.go   # TORCH HTTP client</span></span>
<span class="line"><span>│   │   ├── dimp_client.go    # DIMP HTTP client</span></span>
<span class="line"><span>│   │   ├── validation_client.go # FHIR validation HTTP client</span></span>
<span class="line"><span>│   │   ├── state.go          # State persistence</span></span>
<span class="line"><span>│   │   └── config.go         # Configuration loader</span></span>
<span class="line"><span>│   ├── ui/                   # Progress indicators</span></span>
<span class="line"><span>│   │   ├── progress.go       # Progress bars</span></span>
<span class="line"><span>│   │   ├── eta.go            # ETA calculation</span></span>
<span class="line"><span>│   │   └── throughput.go     # Throughput display</span></span>
<span class="line"><span>│   └── lib/                  # Pure utilities</span></span>
<span class="line"><span>│       ├── retry.go          # Retry logic</span></span>
<span class="line"><span>│       ├── fhir.go           # FHIR parsing</span></span>
<span class="line"><span>│       └── logging.go        # Logging</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>│   ├── unit/                 # Unit tests</span></span>
<span class="line"><span>│   ├── integration/          # Integration tests</span></span>
<span class="line"><span>│   └── contract/             # HTTP service contracts</span></span>
<span class="line"><span>├── config/</span></span>
<span class="line"><span>│   └── aether.example.yaml   # Example configuration</span></span>
<span class="line"><span>└── jobs/                     # Runtime job data (gitignored)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br></div></div><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><p>Aether follows three core principles defined in the project constitution:</p><h3 id="i-functional-programming" tabindex="-1">I. Functional Programming <a class="header-anchor" href="#i-functional-programming" aria-label="Permalink to &quot;I. Functional Programming&quot;">​</a></h3><ul><li><strong>Immutability</strong>: Data structures are immutable by default</li><li><strong>Pure Functions</strong>: Business logic uses pure functions whenever possible</li><li><strong>Explicit Side Effects</strong>: I/O and mutations isolated to service boundaries</li><li><strong>Function Composition</strong>: Complex logic built from small, composable functions</li></ul><p>Benefits:</p><ul><li>Easier to test (no hidden state)</li><li>Easier to reason about (input → output)</li><li>Easier to refactor (no side effects to track)</li><li>Concurrent safety (no shared mutable state)</li></ul><h3 id="ii-test-driven-development-tdd" tabindex="-1">II. Test-Driven Development (TDD) <a class="header-anchor" href="#ii-test-driven-development-tdd" aria-label="Permalink to &quot;II. Test-Driven Development (TDD)&quot;">​</a></h3><ul><li>Tests written first, implementation follows</li><li>Red-Green-Refactor cycle strictly enforced</li><li>Comprehensive coverage (unit, integration, contract tests)</li></ul><p>Benefits:</p><ul><li>Specifications written as tests</li><li>Faster feedback loop</li><li>Fewer bugs in production</li><li>Documentation via examples</li></ul><h3 id="iii-keep-it-simple-stupid-kiss" tabindex="-1">III. Keep It Simple, Stupid (KISS) <a class="header-anchor" href="#iii-keep-it-simple-stupid-kiss" aria-label="Permalink to &quot;III. Keep It Simple, Stupid (KISS)&quot;">​</a></h3><ul><li>Single binary, no microservices</li><li>File-based state, no database</li><li>Standard library-first approach</li><li>External services handle domain complexity</li></ul><p>Benefits:</p><ul><li>Easy to deploy (single binary)</li><li>Easy to understand (clear dependencies)</li><li>Easy to extend (add new service clients)</li><li>No infrastructure overhead</li></ul><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><h3 id="pipeline-execution-flow" tabindex="-1">Pipeline Execution Flow <a class="header-anchor" href="#pipeline-execution-flow" aria-label="Permalink to &quot;Pipeline Execution Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. User Input</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>2. Load Configuration (aether.yaml)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>3. Initialize Job (UUID, state directory)</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>4. Execute Pipeline Steps (in order)</span></span>
<span class="line"><span>   ├─→ Import Step (required, one of):</span></span>
<span class="line"><span>   │   ├─→ torch: Extract FHIR from TORCH via CRTDL</span></span>
<span class="line"><span>   │   ├─→ local_import: Load FHIR from local directory</span></span>
<span class="line"><span>   │   └─→ http_import: Download FHIR from HTTP URL</span></span>
<span class="line"><span>   │   └─→ Save results to job directory</span></span>
<span class="line"><span>   ├─→ Validation Step (if enabled): FHIR data quality checks</span></span>
<span class="line"><span>   │   └─→ Write OperationOutcome reports</span></span>
<span class="line"><span>   ├─→ DIMP Step (if enabled): Pseudonymization</span></span>
<span class="line"><span>   │   └─→ Save de-identified data</span></span>
<span class="line"><span>   └─→ [Additional steps: flattening, send, ...]</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>5. Persist Job State</span></span>
<span class="line"><span>   ├─→ Step status (completed/failed)</span></span>
<span class="line"><span>   ├─→ Output data (NDJSON)</span></span>
<span class="line"><span>   └─→ Logs</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>6. Return Results to User</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><h3 id="state-persistence" tabindex="-1">State Persistence <a class="header-anchor" href="#state-persistence" aria-label="Permalink to &quot;State Persistence&quot;">​</a></h3><p>Job state is persisted to JSON files in the jobs directory:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jobs/</span></span>
<span class="line"><span>└── {job-id}/</span></span>
<span class="line"><span>    ├── status.json               # Job metadata and step status</span></span>
<span class="line"><span>    ├── config.json               # Configuration snapshot</span></span>
<span class="line"><span>    ├── import/</span></span>
<span class="line"><span>    │   ├── Patient.ndjson.zst    # Compressed FHIR data (zstd)</span></span>
<span class="line"><span>    │   └── Observation.ndjson.zst</span></span>
<span class="line"><span>    ├── validation/</span></span>
<span class="line"><span>    │   ├── Patient.validation.ndjson     # OperationOutcome reports</span></span>
<span class="line"><span>    │   └── Observation.validation.ndjson</span></span>
<span class="line"><span>    ├── pseudonymized/</span></span>
<span class="line"><span>    │   ├── Patient.ndjson.zst    # De-identified data (zstd)</span></span>
<span class="line"><span>    │   └── Observation.ndjson.zst</span></span>
<span class="line"><span>    └── logs.txt                  # Execution logs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p><strong>Note</strong>: File extension is <code>.ndjson.zst</code> when compression is enabled (default) or <code>.ndjson</code> when disabled.</p><p>This enables:</p><ul><li><strong>Resume capability</strong>: Continue failed pipelines without reprocessing</li><li><strong>Audit trail</strong>: Full history of what was processed</li><li><strong>Debugging</strong>: Inspect intermediate results</li></ul><h2 id="service-integration" tabindex="-1">Service Integration <a class="header-anchor" href="#service-integration" aria-label="Permalink to &quot;Service Integration&quot;">​</a></h2><h3 id="torch-integration" tabindex="-1">TORCH Integration <a class="header-anchor" href="#torch-integration" aria-label="Permalink to &quot;TORCH Integration&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Command (with .crtdl file)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Aether (torch import step) → TORCH Server</span></span>
<span class="line"><span>    ├─→ Submit CRTDL query</span></span>
<span class="line"><span>    ├─→ Poll extraction status (5s intervals)</span></span>
<span class="line"><span>    └─→ Download FHIR NDJSON results</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Save to job directory</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="dimp-integration" tabindex="-1">DIMP Integration <a class="header-anchor" href="#dimp-integration" aria-label="Permalink to &quot;DIMP Integration&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Import Results (FHIR Bundles)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Aether → DIMP Service</span></span>
<span class="line"><span>    ├─→ Split large bundles (if needed)</span></span>
<span class="line"><span>    ├─→ Send for pseudonymization</span></span>
<span class="line"><span>    └─→ Receive de-identified results</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Persisted Results</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="performance-characteristics" tabindex="-1">Performance Characteristics <a class="header-anchor" href="#performance-characteristics" aria-label="Permalink to &quot;Performance Characteristics&quot;">​</a></h2><h3 id="memory-usage" tabindex="-1">Memory Usage <a class="header-anchor" href="#memory-usage" aria-label="Permalink to &quot;Memory Usage&quot;">​</a></h3><ul><li>Streams FHIR NDJSON line-by-line (no buffering entire files)</li><li>NDJSON scanner buffer supports lines up to 100MB by default (configurable via <code>pipeline.max_ndjson_line_size_mb</code>) to handle large FHIR Bundles</li><li>Job state loaded only when needed</li><li>Progress bars updated incrementally</li></ul><h3 id="disk-usage" tabindex="-1">Disk Usage <a class="header-anchor" href="#disk-usage" aria-label="Permalink to &quot;Disk Usage&quot;">​</a></h3><ul><li>One job directory per execution</li><li>Can clean up old jobs with <code>aether job delete</code></li><li><strong>Zstd compression</strong> reduces file sizes by 4-7x (enabled by default)</li><li>Files use <code>.ndjson.zst</code> extension when compressed</li><li>Automatic detection of both compressed and uncompressed files for backward compatibility</li></ul><h3 id="network-usage" tabindex="-1">Network Usage <a class="header-anchor" href="#network-usage" aria-label="Permalink to &quot;Network Usage&quot;">​</a></h3><ul><li>Exponential backoff retry strategy (reduces unnecessary requests)</li><li>Configurable polling intervals for TORCH</li><li>Automatic bundle splitting for DIMP</li></ul><h3 id="compression" tabindex="-1">Compression <a class="header-anchor" href="#compression" aria-label="Permalink to &quot;Compression&quot;">​</a></h3><p>Aether uses zstd compression (via <code>github.com/klauspost/compress/zstd</code>) for all pipeline output files:</p><ul><li><strong>Default enabled</strong>: Compression is on by default, configurable via <code>compression.enabled</code></li><li><strong>Configurable levels</strong>: <code>fastest</code>, <code>default</code>, <code>better</code>, <code>best</code> trade off speed vs ratio</li><li><strong>Transparent I/O</strong>: <code>OpenFileForReading()</code> auto-detects compressed files</li><li><strong>Backward compatible</strong>: Reads both <code>.ndjson</code> and <code>.ndjson.zst</code> files seamlessly</li></ul><p><strong>Compression ratios</strong> (typical FHIR NDJSON data):</p><table tabindex="0"><thead><tr><th>Level</th><th>Ratio</th><th>Write Speed</th></tr></thead><tbody><tr><td>fastest</td><td>~3-4x</td><td>~500 MB/s</td></tr><tr><td>default</td><td>~4-5x</td><td>~200 MB/s</td></tr><tr><td>better</td><td>~5-6x</td><td>~100 MB/s</td></tr><tr><td>best</td><td>~6-7x</td><td>~50 MB/s</td></tr></tbody></table><h2 id="extensibility" tabindex="-1">Extensibility <a class="header-anchor" href="#extensibility" aria-label="Permalink to &quot;Extensibility&quot;">​</a></h2><p>Adding new pipeline steps:</p><ol><li><strong>Define the step</strong> in <code>internal/models/step.go</code></li><li><strong>Implement the logic</strong> in <code>internal/pipeline/{step_name}.go</code></li><li><strong>Add tests</strong> in <code>tests/unit/{step_name}_test.go</code></li><li><strong>Update CLI</strong> to recognize new step</li><li><strong>Update configuration</strong> documentation</li></ol><p>Example: The validation step was added by following this pattern:</p><ul><li><code>internal/pipeline/validation.go</code> — step logic (chunking, concurrent validation)</li><li><code>internal/services/validation_client.go</code> — HTTP client for the validation service</li><li><code>tests/unit/pipeline_validation_test.go</code> — unit tests</li><li>Documentation in <code>docs/guides/steps/validation.md</code></li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./../getting-started/installation.html">Design Principles</a> - More details on principles</li><li><a href="./testing.html">Testing</a> - Testing strategies and examples</li><li><a href="./contributing.html">Contributing</a> - How to contribute to Aether</li><li><a href="./coding-guidelines.html">Coding Guidelines</a> - Code style and standards</li></ul>`,56)])])}const m=n(l,[["render",p]]);export{u as __pageData,m as default};
